function studioIcon(name){return `<svg class="studioIcon" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${studioIcons[name]||studioIcons.workspace}</svg>`}
const studioDefaults={accent:'forest',density:'comfortable',motion:'system',view:'grid',pins:[]};
let studioPrefs={...studioDefaults};
try{const p=JSON.parse(localStorage.getItem('studio-ui-v1')||'{}');studioPrefs={accent:['forest','cobalt'].includes(p.accent)?p.accent:'forest',density:p.density==='compact'?'compact':'comfortable',motion:p.motion==='reduced'?'reduced':'system',view:p.view==='list'?'list':'grid',pins:Array.isArray(p.pins)?p.pins.filter(x=>typeof x==='string').slice(0,1000):[]}}catch{}
function applyStudioPreferences(){document.documentElement.dataset.accent=studioPrefs.accent;document.documentElement.dataset.density=studioPrefs.density;document.documentElement.dataset.motion=studioPrefs.motion}
function saveStudioPreferences(){applyStudioPreferences();try{localStorage.setItem('studio-ui-v1',JSON.stringify(studioPrefs))}catch{toast('Preferences could not be saved in this browser.')}}
applyStudioPreferences();
let libraryQuery='',libraryFilter='all',librarySort='recent',templateFilter='all';
productRoutes.push('library','templates','settings','guide');
accountMenu.splice(0,accountMenu.length,...[['dashboard','dashboard','Overview'],['library','library','Project library'],['templates','templates','Starter templates'],['workspace','workspace','Design workspace'],['premium','premium','Premium'],['billing','billing','Billing'],['profile','profile','Profile & account'],['settings','settings','Preferences'],['guide','guide','Studio guide']]);
accountShell=function(content,title,kicker='YOUR CONNECTED WORKSPACE'){
 return `<a href="#studioMain" class="skipLink">Skip to content</a><div class="accountLayout"><aside class="accountSidebar">${logo()}<div class="sidebarLabel">YOUR STUDIO</div><nav aria-label="Account navigation">${accountMenu.map(([r,i,n],idx)=>`${idx===4?'<span class="sidebarLabel secondaryLabel">ACCOUNT & RESOURCES</span>':''}<a href="#/${r}" ${productRoute===r?'aria-current="page"':''} class="${productRoute===r?'selected':''}">${studioIcon(i)}<span>${n}</span></a>`).join('')}</nav><div class="sidebarTip"><span class="sidebarTipIcon">${studioIcon('sketch')}</span><b>Small ideas. Real progress.</b><p>Begin with an editable starter and make it your own.</p>${routeLink('templates','Browse templates →')}</div><div class="accountSidebarFoot">${routeLink('landing','↗ Back to website')}<button data-logout>${signedIn?'End preview session':'Log in to preview'} →</button></div></aside><div class="accountBody"><header class="accountHeader"><span class="headerBreadcrumb">Studio <i>/</i> ${esc(title)}</span><div class="accountHeaderActions"><button class="studioSearch" data-studio-search aria-label="Search pages and actions">${studioIcon('search')}<span>Search studio</span><kbd>Ctrl K</kbd></button>${routeLink('profile',`<span class="avatar">${initials()}</span><span class="srOnly">My profile</span>`)}</div></header><main id="studioMain" tabindex="-1" class="accountMain"><div class="accountHeading"><div><span class="eyebrow">${kicker}</span><h1>${esc(title)}</h1></div><span class="modeBadge">LOCAL PREVIEW</span></div>${content}</main><div class="accountFooter"><span>● Saved on this device</span><span>Engineering Design Studio · Concept workspace</span></div></div></div>`;
};
const originalDashboard=dashboardPage;
dashboardPage=function(premium=false){
 if(premium)return originalDashboard(true);
 const revisions=projects.reduce((n,p)=>n+p.revisions.length,0),notes=projects.reduce((n,p)=>n+p.notes.length,0);
 const p=projects.find(p=>p.id===current?.id)||projects[0];
 const tasks=p?.buildTasks||[],done=tasks.filter(t=>t.done).length;
 return accountShell(`<section class="studioWelcome"><div><span class="welcomeEyebrow"><span></span> YOUR IDEAS, IN MOTION</span><h2>A little curiosity.<br><em>A lot of possibility.</em></h2><p>${account?'Welcome back, '+esc(account.name.split(' ')[0])+'. ':''}Give your next idea a place to take shape.</p><div class="heroActions"><button class="primary" data-create-project>＋ Create a project</button>${routeLink('templates','Explore templates '+studioIcon('arrow'),'welcomeLink')}</div></div><div class="welcomeBlueprint" aria-hidden="true">${templateArt('mechanical')}<div><span>CONCEPT 001</span><span>DESIGN → DISCOVER</span></div></div></section><div class="dashboardMetrics">${metric('YOUR PROJECTS',projects.length,'Ideas in your studio')}${metric('SAVED REVISIONS',revisions,'Snapshots you can revisit')}${metric('EVIDENCE RECORDS',notes,'Notes and calculations')}${metric('CURRENT PLAN','Free','Studio preview access')}</div><section class="toolShelf" aria-label="Engineering tools">${[['design','workspace','Design','Dimensions & geometry'],['sketch','sketch','Sketch','Draw your concept'],['analysis','motion','Motion','Explore a full cycle'],['electronics','circuit','Electronics','Calculate a DC circuit'],['manufacturing','build','Build planning','Tasks & batch costs']].map(([r,i,t,d])=>`<a href="#/workspace?tool=${r}"><span class="toolIcon">${studioIcon(i)}</span><div><b>${t}</b><small>${d}</small></div><span class="toolArrow">↗</span></a>`).join('')}</section><section class="projectSection"><div class="sectionTitle"><div><span class="eyebrow">KEEP YOUR MOMENTUM</span><h2>Your project desk</h2></div>${routeLink('library','View all projects →','textLink')}</div><div class="dashboardProjects">${projects.slice(-3).reverse().map(p=>studioProjectCard(p)).join('')||emptyStudio('Your next idea starts here.','Create a project or choose a starter template.')}</div></section><div class="studioBottom"><section class="studioPanel"><div class="sectionTitle"><div><span class="eyebrow">NEXT STEPS</span><h2>Move your concept forward.</h2></div>${studioIcon('check')}</div><p class="panelDescription">${p?esc(p.name):'Start a project to track your progress.'}</p>${p?`<div class="nextSteps">${[[p.parts.length>0,'Define the assembly','Add parts and planning costs.','assembly'],[p.notes.length>0,'Record your reasoning','Save an assumption or calculation.','evidence'],[p.revisions.length>0,'Keep a checkpoint','Capture a recoverable revision.','revisions']].map(([complete,title,desc,tab])=>`<a href="#/workspace?tool=${tab}"><span class="stepIndicator ${complete?'done':''}">${complete?studioIcon('check'):''}</span><div><b>${title}</b><small>${desc}</small></div><span>↗</span></a>`).join('')}</div><div class="panelFoot">${tasks.length?`${done} of ${tasks.length} build tasks complete`:'Build checklist ready when you are'} · Planning progress</div>`:''}</section><section class="studioPanel featuredStarter"><span class="eyebrow">SKIP THE BLANK PAGE</span><h2>A starting point.<br>Not a finished answer.</h2><p>Editable dimensions, a starter brief and practical next steps. Pick a direction and take it somewhere new.</p><div class="starterMini">${templateArt('circuit')}</div>${routeLink('templates','Find your starting point '+studioIcon('arrow'),'pbutton')}</section></div>`,'Overview','DESIGN. UNDERSTAND. CREATE.');
};
function templateArt(type){
 const paths=type==='circuit'?'<path d="M55 95V45h105m50 0h95v110H55v-35"/><circle cx="55" cy="108" r="17"/><path d="M160 45l5-10 8 20 8-20 8 20 8-20 8 20 5-10M48 104h14m-7-7v14M49 116h12"/><circle cx="305" cy="45" r="4"/><circle cx="305" cy="155" r="4"/><path d="M245 29h35l-6-5m6 5-6 5"/>':type==='sketch'?'<rect x="75" y="35" width="210" height="135" rx="16"/><circle cx="100" cy="60" r="6"/><circle cx="260" cy="60" r="6"/><circle cx="100" cy="145" r="6"/><circle cx="260" cy="145" r="6"/><rect x="135" y="65" width="90" height="75" rx="5"/><path d="M75 190h210M75 182v16m210-16v16M55 35v135m-7-135h14m-14 135h14"/>':'<path d="M35 165h300M45 155V65" opacity=".4"/><circle cx="108" cy="106" r="51"/><circle cx="108" cy="106" r="8"/><path d="m108 106 26-38 145 38" stroke-width="9"/><rect x="257" y="82" width="43" height="48" rx="4"/><circle cx="134" cy="68" r="7"/><circle cx="278" cy="106" r="6"/><path d="M185 45h115m-115-6v12m115-12v12" stroke-width="1"/>';
 return `<svg viewBox="0 0 360 210" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths}</svg>`;
}
function projectCategory(p){return /electronic/i.test(p.kind||'')?'electronics':/electromechanical/i.test(p.kind||'')?'mixed':'mechanical'}
function studioProjectCard(p){const pinned=studioPrefs.pins.includes(p.id),category=projectCategory(p);return `<article class="studioProject"><div class="projectArt ${category}">${templateArt(category==='electronics'?'circuit':'mechanical')}<span class="projectType">${category==='mixed'?'ELECTROMECHANICAL':category.toUpperCase()}</span><button class="pinProject ${pinned?'pinned':''}" data-pin-project="${esc(p.id)}" aria-label="${pinned?'Unpin':'Pin'} ${esc(p.name)}" aria-pressed="${pinned}">${studioIcon('star')}</button></div><div class="studioProjectBody"><span class="conceptLabel">● CONCEPT STUDY</span><h3>${esc(p.name)}</h3><p>${p.parts.length} parts <span>·</span> ${p.notes.length} notes <span>·</span> ${p.revisions.length} revisions</p><div class="projectCardActions"><button class="openProject" data-open-project="${esc(p.id)}">Open project ${studioIcon('arrow')}</button><div><button data-duplicate-project="${esc(p.id)}" aria-label="Duplicate ${esc(p.name)}" title="Duplicate project">⧉</button><button data-export-project="${esc(p.id)}" aria-label="Export ${esc(p.name)}" title="Export JSON">↓</button></div></div></div></article>`}
function emptyStudio(title,detail){return `<div class="studioEmpty">${studioIcon('library')}<h3>${title}</h3><p>${detail}</p>${routeLink('templates','Browse starter templates →','pbutton')}</div>`}
function filteredStudioProjects(){let rows=projects.filter(p=>(p.name+' '+(p.kind||'')).toLowerCase().includes(libraryQuery.toLowerCase())&&(libraryFilter==='all'||libraryFilter==='pinned'&&studioPrefs.pins.includes(p.id)||projectCategory(p)===libraryFilter));if(librarySort==='name')rows.sort((a,b)=>a.name.localeCompare(b.name));else if(librarySort==='revisions')rows.sort((a,b)=>b.revisions.length-a.revisions.length);else rows.reverse();return rows}
function libraryResults(){const rows=filteredStudioProjects();return rows.map(studioProjectCard).join('')||emptyStudio('No projects found.','Try a different search or filter, or start a new concept.')}
function libraryPage(){return accountShell(`<div class="pageLead"><p>Keep every concept close. Find it, develop it, make it yours.</p><div><button id="dashboardImport">↑ Import JSON</button><button class="primary" data-create-project>＋ New project</button></div></div><section class="libraryToolbar" aria-label="Project filters"><label class="searchField">${studioIcon('search')}<input id="librarySearch" placeholder="Search projects or disciplines…" aria-label="Search project library" value="${esc(libraryQuery)}"></label><label class="sortControl"><span>Sort</span><select id="librarySort" aria-label="Sort projects">${[['recent','Library order'],['name','Name: A–Z'],['revisions','Most revisions']].map(([v,n])=>`<option value="${v}" ${librarySort===v?'selected':''}>${n}</option>`).join('')}</select></label><div class="viewSwitch" aria-label="Project layout"><button data-library-view="grid" aria-label="Grid view" aria-pressed="${studioPrefs.view==='grid'}">▦</button><button data-library-view="list" aria-label="List view" aria-pressed="${studioPrefs.view==='list'}">☰</button></div></section><div class="filterRow" aria-label="Filter projects">${[['all','All projects'],['pinned','★ Pinned'],['mechanical','Mechanical'],['electronics','Electronics'],['mixed','Electromechanical']].map(([v,n])=>`<button data-library-filter="${v}" aria-pressed="${libraryFilter===v}">${n}</button>`).join('')}<span id="libraryCount" role="status">${filteredStudioProjects().length} projects</span></div><div id="libraryResults" class="dashboardProjects libraryProjects ${studioPrefs.view==='list'?'listView':''}">${libraryResults()}</div><div class="libraryHint">${studioIcon('guide')} Tip: pin a project to find it quickly. Export a JSON copy to keep a backup.</div>`,'Project library','A HOME FOR YOUR ORIGINAL IDEAS')}
const studioTemplates=[
 {id:'slider',category:'mechanical',art:'mechanical',name:'Slider-crank study',tag:'MOTION & MECHANISMS',description:'Explore how rotary motion becomes linear motion. Compare geometry and capture your findings.',details:['80 mm stroke · 150 mm rod','Four starter BOM entries','Motion & evidence workflow'],data:{name:'Slider-crank study',kind:'Mechanical assembly',stroke:80,rod:150,rpm:600,parts:structuredClone(initial.parts)},tasks:['Inspect a full motion cycle','Compare two connecting-rod lengths','Record an assumption and save a revision']},
 {id:'dc',category:'electronics',art:'circuit',name:'DC resistor experiment',tag:'ELECTRONICS BASICS',description:'Explore voltage, resistance and power with an ideal DC model and a simple test plan.',details:['5 V supply · 1 kΩ resistance','0.25 W entered resistor rating','Editable electrical brief'],data:{name:'DC resistor experiment',kind:'Electronics project',circuit:{voltage:5,resistance:1000,rating:.25},parts:[{name:'1 kΩ resistor',material:'Purchased component',qty:1,price:0}],electrical:'Concept: an ideal voltage source connected to a resistor. Compare calculated current and power at different supply voltages. Hardware tolerances and thermal derating require separate review.'},tasks:['Calculate ideal current and power','Record resistor tolerance and rating assumptions','Define a measurement procedure']},
 {id:'enclosure',category:'mechanical',art:'sketch',name:'Enclosure concept',tag:'SKETCH & FABRICATION',description:'Start with a 2D face layout. Refine the envelope, document mounting needs and plan fabrication.',details:['210 × 135 mm face sketch','Four mounting-hole markers','Material & fabrication checklist'],data:{name:'Enclosure concept',kind:'Mechanical assembly',sketch:[{type:'rect',x:140,y:100,w:210,h:135},{type:'circle',x:160,y:120,r:4},{type:'circle',x:330,y:120,r:4},{type:'circle',x:160,y:215,r:4},{type:'circle',x:330,y:215,r:4}],parts:[]},tasks:['Set the required component envelope','Define mounting-hole sizes and clearances','Choose material and fabrication process','Create a dimensioned drawing outside this concept sketch']},
 {id:'actuator',category:'mixed',art:'mechanical',name:'Actuator planning brief',tag:'MECHANICS + ELECTRONICS',description:'Connect a mechanism study with motor, driver and control requirements in one project.',details:['40 mm stroke · 100 mm rod','Editable power & control brief','Assembly and test planning'],data:{name:'Actuator planning brief',kind:'Electromechanical prototype',stroke:40,rod:100,rpm:120,parts:[],electrical:'To define: load, duty cycle, travel limits, motor/driver ratings, supply protection and control strategy. This template does not size a motor or simulate a control system.'},tasks:['Document load and duty cycle','Specify travel limits and operating speed','Select motor and driver using verified calculations','Define a controlled test procedure']}
];
function buildStudioTemplate(id,name){const t=studioTemplates.find(t=>t.id===id);if(!t)throw Error('Unknown starter template.');return {...structuredClone(initial),id:crypto.randomUUID(),parts:[],notes:[],revisions:[],...structuredClone(t.data),name:name.trim(),notes:[{title:'Starter brief · '+t.name,body:t.description+'\nConcept starting values only. Review all dimensions, ratings and prices before using them. Zero prices mean unquoted components. The shared motion tool remains a slider-crank model, regardless of project type.',type:'Research',date:new Date().toISOString()}],buildTasks:t.tasks.map(name=>({name,done:false}))}}
async function saveNewStudioProject(project){const previous=current;project.id=crypto.randomUUID();projects.push(project);current=project;try{persist()}catch(error){projects.pop();current=previous;throw Error('Project could not be saved. Export a backup and check browser storage.')}return project}
function templateCards(){return studioTemplates.filter(t=>templateFilter==='all'||t.category===templateFilter).map(t=>`<article class="templateCard"><div class="templateArt ${t.category}">${templateArt(t.art)}<span>EDITABLE STARTER</span></div><div class="templateBody"><span class="eyebrow">${t.tag}</span><h2>${t.name}</h2><p>${t.description}</p><ul>${t.details.map(d=>`<li>${studioIcon('check')}${d}</li>`).join('')}</ul><button class="primary" data-use-template="${t.id}">Use this template ${studioIcon('arrow')}</button></div></article>`).join('')}
function templatesPage(){return accountShell(`<div class="pageLead"><p>Start with a question worth exploring. Every template is yours to edit.</p>${routeLink('library','Open project library →','textLink')}</div><div class="filterRow">${[['all','All starters'],['mechanical','Mechanical'],['electronics','Electronics'],['mixed','Electromechanical']].map(([v,n])=>`<button data-template-filter="${v}" aria-pressed="${templateFilter===v}">${n}</button>`).join('')}</div><div id="templateResults" class="templateGrid">${templateCards()}</div><p class="templateDisclaimer">Starting values are examples, not validated engineering designs. Verify materials, dimensions and component ratings for your application.</p>`,'Starter templates','LESS SETUP. MORE EXPLORATION.')}
function settingsPage(){return accountShell(`<div class="pageLead"><p>Make the studio feel right for the way you work.</p></div><form id="studioPreferences" class="preferencesPanel studioPanel"><div class="settingsRow"><div><span class="eyebrow">01 / APPEARANCE</span><h2>Your studio accent</h2><p>A little personality, with a consistent light workspace.</p></div><fieldset class="accentOptions"><legend class="srOnly">Studio accent</legend>${[['forest','Forest'],['cobalt','Cobalt']].map(([v,n])=>`<label><input type="radio" name="accent" value="${v}" ${studioPrefs.accent===v?'checked':''}><span class="colorSwatch ${v}"></span>${n}</label>`).join('')}</fieldset></div><div class="settingsRow"><div><span class="eyebrow">02 / LAYOUT</span><h2>Interface density</h2><p>Choose extra breathing room or fit more on your screen.</p></div><select name="density" aria-label="Interface density"><option value="comfortable" ${studioPrefs.density==='comfortable'?'selected':''}>Comfortable</option><option value="compact" ${studioPrefs.density==='compact'?'selected':''}>Compact</option></select></div><div class="settingsRow"><div><span class="eyebrow">03 / ACCESSIBILITY</span><h2>Reduce interface motion</h2><p>Limit decorative transitions. Mechanism playback stays under your control.</p></div><label class="toggleOption"><input type="checkbox" name="motion" ${studioPrefs.motion==='reduced'?'checked':''}><span>Reduce motion</span></label></div><div class="settingsActions"><span>Preferences are saved in this browser.</span><button type="button" id="resetStudioPreferences">Restore defaults</button><button type="submit" class="primary">Save preferences</button></div><p id="preferenceStatus" role="status"></p></form><div class="settingsLinks"><a href="#/profile">${studioIcon('profile')}<div><b>Profile & account</b><p>Personal details and available account controls</p></div><span>↗</span></a><a href="#/billing">${studioIcon('billing')}<div><b>Billing & plan</b><p>Review your current plan and billing records</p></div><span>↗</span></a></div>`,'Preferences','A WORKSPACE THAT FEELS LIKE YOURS')}
const studioGuides=[['Design & motion','Edit stroke, connecting-rod length and speed. Use Motion to inspect an ideal slider-crank cycle. This model does not calculate stress, fatigue or motor sizing.','design'],['Sketch a concept','Draw rectangles, circles and lines on the 2D canvas. Undo the last shape or export an SVG. Sketches are concept geometry, not manufacturing drawings.','sketch'],['Parts & costs','Add assembly components and planning prices. In Build planning, include labor, tooling and overhead. Unquoted components should be reviewed before treating a total as useful.','assembly'],['Electronics','Enter voltage, resistance and resistor rating to calculate ideal DC current and power. Real circuits need separate checks for tolerances, heat, transients and protection.','electronics'],['Evidence & revisions','Record your reasoning and save a snapshot before changing a design. Compare or restore previous revisions. Calculation records can become outdated after parameter changes.','evidence'],['Exports & backups','Export a project as JSON for re-import. Motion samples export to CSV, sketches to SVG, and the build report to HTML. Browser-local projects need regular exported backups.','manufacturing']];
function guidePage(){return accountShell(`<div class="guideHero"><div><span class="eyebrow">A SMALL GUIDE FOR BIG IDEAS</span><h2>Find your next step.</h2><p>Practical tools, clear assumptions, and a record of what you learn.</p></div>${studioIcon('guide')}</div><div class="guideGrid">${studioGuides.map(([title,body,tool],i)=>`<details class="guideItem" ${i===0?'open':''}><summary><span>0${i+1}</span>${title}<b>＋</b></summary><div><p>${body}</p>${routeLink('workspace?tool='+tool,'Open this tool →','textLink')}</div></details>`).join('')}</div><section class="studioPanel shortcutPanel"><div><h2>Less reaching. More making.</h2><p>Use the command menu to find pages and tools.</p></div><button data-studio-search><kbd>Ctrl / ⌘</kbd> + <kbd>K</kbd> Open search</button></section>`,'Studio guide','GET TO KNOW YOUR WORKSPACE')}
function studioWorkspaceTab(){const value=new URLSearchParams(location.hash.split('?')[1]||'').get('tool');return tabs.some(([id])=>id===value)?value:'design'}
function bindStudioCards(root=document){
 root.querySelectorAll('[data-open-project]').forEach(b=>b.onclick=()=>openProductProject(b.dataset.openProject));
 root.querySelectorAll('[data-pin-project]').forEach(b=>b.onclick=()=>{const id=b.dataset.pinProject;studioPrefs.pins=studioPrefs.pins.includes(id)?studioPrefs.pins.filter(x=>x!==id):[...studioPrefs.pins,id];saveStudioPreferences();if(productRoute==='library')refreshLibrary();else{b.classList.toggle('pinned',studioPrefs.pins.includes(id));b.setAttribute('aria-pressed',String(studioPrefs.pins.includes(id)));const p=projects.find(p=>p.id===id);b.setAttribute('aria-label',(studioPrefs.pins.includes(id)?'Unpin ':'Pin ')+(p?.name||'project'))}});
 root.querySelectorAll('[data-export-project]').forEach(b=>b.onclick=()=>{const p=projects.find(p=>p.id===b.dataset.exportProject);if(p)download(p.name.replace(/[^a-z0-9_-]/gi,'-')+'.json',JSON.stringify(p,null,2),'application/json')});
 root.querySelectorAll('[data-duplicate-project]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const p=projects.find(p=>p.id===b.dataset.duplicateProject);if(!p)return;const copy=structuredClone(p);copy.name=p.name.slice(0,180)+' (copy)';await saveNewStudioProject(copy);showProductRoute();toast('Project duplicated')}catch(e){toast(e.message)}finally{b.disabled=false}});
}
function refreshLibrary(){const root=$('#libraryResults');if(!root)return;root.innerHTML=libraryResults();root.classList.toggle('listView',studioPrefs.view==='list');$('#libraryCount').textContent=filteredStudioProjects().length+' projects';bindStudioCards(root)}
function bindStudioTemplates(){document.querySelectorAll('[data-use-template]').forEach(b=>b.onclick=()=>{const t=studioTemplates.find(t=>t.id===b.dataset.useTemplate);modal('Start from '+t.name,field('starterName','Project name',t.name)+'<p class="tiny">Creates an editable copy in your current project collection.</p>',()=>{});$('#starterName').required=true;$('#starterName').maxLength=180;$('#modalForm>button[type=submit]').textContent='Create project';$('#modalForm').onsubmit=async e=>{e.preventDefault();const name=$('#starterName').value.trim();if(!name)return;const submit=e.target.querySelector('button[type=submit]');submit.disabled=true;try{await saveNewStudioProject(buildStudioTemplate(t.id,name));$('#dialog').close();location.hash='/workspace?tool='+(t.art==='circuit'?'electronics':t.art==='sketch'?'sketch':'design');toast('Your starter project is ready')}catch(err){toast(err.message)}finally{submit.disabled=false}}})}
const studioBaseBind=bindProduct;
bindProduct=function(){studioBaseBind();bindStudioCards();bindStudioTemplates();document.querySelectorAll('[data-studio-search]').forEach(b=>b.onclick=commandPalette);
 if($('.skipLink'))$('.skipLink').onclick=e=>{e.preventDefault();$('#studioMain').focus();$('#studioMain').scrollIntoView({behavior:'instant'})};
 if($('#librarySearch'))$('#librarySearch').oninput=e=>{libraryQuery=e.target.value;refreshLibrary()};
 if($('#librarySort'))$('#librarySort').onchange=e=>{librarySort=e.target.value;refreshLibrary()};
 document.querySelectorAll('[data-library-filter]').forEach(b=>b.onclick=()=>{libraryFilter=b.dataset.libraryFilter;document.querySelectorAll('[data-library-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));refreshLibrary()});
 document.querySelectorAll('[data-library-view]').forEach(b=>b.onclick=()=>{studioPrefs.view=b.dataset.libraryView;saveStudioPreferences();document.querySelectorAll('[data-library-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));refreshLibrary()});
 document.querySelectorAll('[data-template-filter]').forEach(b=>b.onclick=()=>{templateFilter=b.dataset.templateFilter;document.querySelectorAll('[data-template-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#templateResults').innerHTML=templateCards();bindStudioTemplates()});
 if($('#studioPreferences'))$('#studioPreferences').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);studioPrefs.accent=f.get('accent');studioPrefs.density=f.get('density');studioPrefs.motion=f.get('motion')?'reduced':'system';saveStudioPreferences();$('#preferenceStatus').textContent='Your preferences have been saved.'};
 if($('#resetStudioPreferences'))$('#resetStudioPreferences').onclick=()=>{studioPrefs={...studioDefaults,pins:studioPrefs.pins};saveStudioPreferences();showProductRoute();toast('Appearance preferences restored')};
};
// All tool commands navigate through the existing route/authentication gate.
quickActions.splice(0,quickActions.length,...accountMenu.map(([route,,name])=>['Go to '+name,()=>location.hash='/'+route]),...tabs.map(([id,label])=>['Open '+label,()=>location.hash='/workspace?tool='+id]));
const studioBaseModal=modal;modal=function(...args){const b=$('#modalForm>button[type=submit]');b.textContent='Save';b.disabled=false;studioBaseModal(...args)};
const studioBaseLanding=landingPage;
landingPage=function(){const starters=`<section class="landingStarters"><div class="sectionIntro"><span class="eyebrow">A HEAD START FOR YOUR CURIOSITY</span><h2>Start with something tangible.</h2><p>Four editable starting points. A mechanism, a circuit, an enclosure, or a connected prototype. Make the next decision yours.</p></div><div class="landingStarterGrid">${studioTemplates.slice(0,3).map(t=>`<a href="#/templates"><div class="landingStarterArt ${t.category}">${templateArt(t.art)}<span>↗</span></div><span class="eyebrow">${t.tag}</span><h3>${t.name}</h3><p>${t.details[0]}</p></a>`).join('')}</div><div class="landingStarterFoot"><span>Editable project data · No premium plan required</span>${routeLink('templates','Explore all starter templates →','textLink')}</div></section>`;return studioBaseLanding().replace('<section class="workflowSection">',starters+'<section class="workflowSection">')};
